sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* =========================================================
   CAMPUS FOOD SERVICES ASSISTANT
   SKY BLUE + DEEP BLUE MODERN THEME
   ========================================================= */

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Segoe UI", Arial, sans-serif;
  background: #f0f9ff;
  color: #0f172a;
}


/* =========================================================
   HERO
   ========================================================= */

.cfa-hero {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(circle at 15% 20%, rgba(255,255,255,.18), transparent 25%),
    radial-gradient(circle at 85% 80%, rgba(125,211,252,.25), transparent 30%),
    linear-gradient(
      135deg,
      #0284c7 0%,
      #0369a1 45%,
      #172554 100%
    );

  background-size: 200% 200%;
  color: #ffffff;
  padding: 105px 24px;
  text-align: center;

  animation: cfa-gradient 10s ease infinite;
}

.cfa-hero::before,
.cfa-hero::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.cfa-hero::before {
  width: 350px;
  height: 350px;
  top: -170px;
  left: -100px;
  background: rgba(186,230,253,.18);
  animation: cfa-float 7s ease-in-out infinite;
}

.cfa-hero::after {
  width: 430px;
  height: 430px;
  right: -180px;
  bottom: -230px;
  background: rgba(125,211,252,.14);
  animation: cfa-float 9s ease-in-out infinite reverse;
}

.cfa-hero-inner {
  position: relative;
  z-index: 2;
  max-width: 780px;
  margin: 0 auto;
  animation: cfa-fade-up .8s ease both;
}

.cfa-hero h1 {
  font-size: 40px;
  margin: 0 0 18px;
  font-weight: 800;
  letter-spacing: -.8px;
  text-shadow: 0 4px 20px rgba(0,0,0,.18);
}

.cfa-hero p {
  max-width: 700px;
  margin: 0 auto 32px;
  font-size: 16px;
  line-height: 1.8;
  color: #e0f2fe;
}

.cfa-hero-btn {
  display: inline-block;
  background: #ffffff;
  color: #075985;
  padding: 14px 32px;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 800;
  text-decoration: none;

  box-shadow: 0 10px 30px rgba(0,0,0,.20);

  transition:
    transform .25s ease,
    box-shadow .25s ease,
    background .25s ease;
}

.cfa-hero-btn:hover {
  background: #e0f2fe;
  color: #0369a1;
  transform: translateY(-4px);
  box-shadow: 0 15px 35px rgba(0,0,0,.25);
  text-decoration: none;
}

.cfa-hero-btn:active {
  transform: translateY(-1px);
}


/* =========================================================
   WELCOME
   ========================================================= */

.cfa-welcome {
  padding: 75px 24px;
  background: linear-gradient(
    180deg,
    #ffffff 0%,
    #f0f9ff 100%
  );
}

.cfa-welcome-inner {
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.cfa-welcome-inner h2 {
  margin: 0 0 15px;
  font-size: 28px;
  font-weight: 800;
  color: #0c4a6e;
}

.cfa-welcome-inner > p {
  max-width: 760px;
  margin: 0 auto 40px;
  color: #475569;
  font-size: 14px;
  line-height: 1.8;
}

.cfa-welcome-points {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  text-align: left;
}

.cfa-welcome-point {
  display: flex;
  gap: 14px;
  align-items: flex-start;

  padding: 22px;

  background: rgba(255,255,255,.85);
  border: 1px solid #bae6fd;
  border-radius: 15px;

  box-shadow: 0 8px 25px rgba(2,132,199,.07);

  transition:
    transform .25s ease,
    box-shadow .25s ease,
    border-color .25s ease;
}

.cfa-welcome-point:hover {
  transform: translateY(-6px);
  border-color: #38bdf8;
  box-shadow: 0 15px 35px rgba(2,132,199,.14);
}

.cfa-wp-icon {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  background: #e0f2fe;
  border-radius: 12px;

  font-size: 21px;

  transition: transform .3s ease;
}

.cfa-welcome-point:hover .cfa-wp-icon {
  transform: scale(1.12) rotate(-5deg);
}

.cfa-welcome-point b {
  display: block;
  margin-bottom: 5px;

  color: #0c4a6e;
  font-size: 14px;
  font-weight: 800;
}

.cfa-welcome-point span {
  color: #64748b;
  font-size: 12px;
  line-height: 1.6;
}


/* =========================================================
   SERVICES
   ========================================================= */

.cfa-services {
  max-width: 1150px;
  margin: 0 auto;
  padding: 80px 24px;
}

.cfa-services h2 {
  margin: 0 0 42px;

  text-align: center;

  font-size: 29px;
  font-weight: 800;

  color: #0c4a6e;
}

.cfa-services h2::after {
  content: "";

  display: block;

  width: 65px;
  height: 4px;

  margin: 13px auto 0;

  border-radius: 10px;

  background: linear-gradient(
    90deg,
    #38bdf8,
    #0284c7
  );
}

.cfa-services-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.cfa-service-card {
  position: relative;
  overflow: hidden;

  min-height: 180px;

  background: #ffffff;

  border: 1px solid #bae6fd;
  border-radius: 16px;

  padding: 23px;

  box-shadow: 0 7px 20px rgba(2,132,199,.06);

  transition:
    transform .3s ease,
    box-shadow .3s ease,
    border-color .3s ease;
}

.cfa-service-card::before {
  content: "";

  position: absolute;

  top: 0;
  left: 0;

  width: 100%;
  height: 4px;

  background: linear-gradient(
    90deg,
    #38bdf8,
    #0284c7,
    #1e3a8a
  );

  transform: scaleX(0);
  transform-origin: left;

  transition: transform .35s ease;
}

.cfa-service-card:hover {
  transform: translateY(-8px);

  border-color: #38bdf8;

  box-shadow:
    0 18px 38px rgba(2,132,199,.15);
}

.cfa-service-card:hover::before {
  transform: scaleX(1);
}

.cfa-service-icon {
  width: 48px;
  height: 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 14px;

  border-radius: 13px;

  background: linear-gradient(
    135deg,
    #e0f2fe,
    #bae6fd
  );

  font-size: 25px;

  transition:
    transform .3s ease,
    box-shadow .3s ease;
}

.cfa-service-card:hover .cfa-service-icon {
  transform: scale(1.12) rotate(-3deg);

  box-shadow:
    0 8px 18px rgba(14,165,233,.18);
}

.cfa-service-card h4 {
  margin: 0 0 8px;

  color: #0c4a6e;

  font-size: 14px;
  font-weight: 800;
  line-height: 1.4;
}

.cfa-service-card p {
  margin: 0;

  color: #64748b;

  font-size: 12px;
  line-height: 1.6;
}


/* =========================================================
   ABOUT
   ========================================================= */

.cfa-about {
  position: relative;
  overflow: hidden;

  padding: 80px 24px;

  background:
    radial-gradient(
      circle at 90% 20%,
      rgba(56,189,248,.15),
      transparent 25%
    ),
    linear-gradient(
      135deg,
      #e0f2fe,
      #f0f9ff
    );
}

.cfa-about-inner {
  position: relative;
  z-index: 2;

  max-width: 900px;
  margin: 0 auto;

  text-align: center;
}

.cfa-about h2 {
  margin: 0 0 17px;

  color: #0c4a6e;

  font-size: 29px;
  font-weight: 800;
}

.cfa-about p {
  margin: 0 auto 32px;

  max-width: 780px;

  color: #475569;

  font-size: 14px;
  line-height: 1.8;
}

.cfa-team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;

  margin-bottom: 25px;
}

.cfa-team-card {
  padding: 21px 15px;

  background: rgba(255,255,255,.9);

  border: 1px solid #bae6fd;
  border-radius: 14px;

  display: flex;
  flex-direction: column;
  gap: 6px;

  box-shadow: 0 7px 20px rgba(2,132,199,.07);

  transition:
    transform .25s ease,
    box-shadow .25s ease;
}

.cfa-team-card:hover {
  transform: translateY(-6px);

  box-shadow:
    0 15px 30px rgba(2,132,199,.13);
}

.cfa-team-card b {
  color: #0c4a6e;

  font-size: 13.5px;
  font-weight: 800;
}

.cfa-team-card span {
  color: #64748b;

  font-size: 11.5px;
  line-height: 1.5;
}

.cfa-college {
  color: #0369a1 !important;

  font-size: 12.5px !important;
  font-weight: 700;
}


/* =========================================================
   CONTACT
   ========================================================= */

.cfa-contact {
  padding: 80px 24px;

  background: #ffffff;
}

.cfa-contact-inner {
  max-width: 950px;
  margin: 0 auto;

  text-align: center;
}

.cfa-contact h2 {
  margin: 0 0 35px;

  color: #0c4a6e;

  font-size: 29px;
  font-weight: 800;
}

.cfa-contact h2::after {
  content: "";

  display: block;

  width: 55px;
  height: 4px;

  margin: 12px auto 0;

  border-radius: 10px;

  background: linear-gradient(
    90deg,
    #38bdf8,
    #0284c7
  );
}

.cfa-contact-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.cfa-contact-card {
  padding: 28px 20px;

  background: linear-gradient(
    180deg,
    #ffffff,
    #f0f9ff
  );

  border: 1px solid #bae6fd;
  border-radius: 16px;

  box-shadow: 0 8px 24px rgba(2,132,199,.07);

  transition:
    transform .25s ease,
    box-shadow .25s ease,
    border-color .25s ease;
}

.cfa-contact-card:hover {
  transform: translateY(-7px);

  border-color: #38bdf8;

  box-shadow:
    0 16px 32px rgba(2,132,199,.14);
}

.cfa-contact-icon {
  width: 52px;
  height: 52px;

  margin: 0 auto 13px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: linear-gradient(
    135deg,
    #e0f2fe,
    #bae6fd
  );

  border-radius: 14px;

  font-size: 25px;
}

.cfa-contact-card b {
  display: block;

  margin-bottom: 6px;

  color: #0c4a6e;

  font-size: 14px;
  font-weight: 800;
}

.cfa-contact-card span {
  color: #64748b;

  font-size: 12px;
  line-height: 1.6;
}


/* =========================================================
   FOOTER
   ========================================================= */

.cfs-footer {
  position: relative;

  overflow: hidden;

  background:
    radial-gradient(
      circle at 85% 20%,
      rgba(56,189,248,.16),
      transparent 28%
    ),
    linear-gradient(
      135deg,
      #082f49 0%,
      #075985 45%,
      #172554 100%
    );

  color: #ffffff;

  padding-top: 58px;
}

.cfs-footer::before {
  content: "";

  position: absolute;

  width: 300px;
  height: 300px;

  top: -180px;
  right: -80px;

  border-radius: 50%;

  background: rgba(125,211,252,.08);

  pointer-events: none;
}

.cfs-footer::after {
  content: "";

  position: absolute;

  width: 230px;
  height: 230px;

  bottom: -150px;
  left: -70px;

  border-radius: 50%;

  background: rgba(56,189,248,.07);

  pointer-events: none;
}

.footer-container {
  position: relative;
  z-index: 2;

  max-width: 1200px;

  margin: 0 auto;

  padding: 0 30px 48px;

  display: grid;

  grid-template-columns: 2fr 1fr 1fr;

  gap: 70px;
}


/* FOOTER BRAND */

.footer-brand {
  max-width: 420px;
}

.footer-brand h3 {
  margin: 0 0 14px;

  color: #ffffff;

  font-size: 23px;
  font-weight: 800;

  letter-spacing: -.4px;
}

.footer-brand h3::after {
  content: "";

  display: block;

  width: 50px;
  height: 4px;

  margin-top: 11px;

  border-radius: 10px;

  background: #38bdf8;
}

.footer-brand p {
  margin: 18px 0 0;

  max-width: 360px;

  color: #bae6fd;

  font-size: 13.5px;
  line-height: 1.8;
}


/* FOOTER COLUMNS */

.footer-column {
  display: flex;

  flex-direction: column;

  align-items: flex-start;

  gap: 13px;
}

.footer-column h4 {
  margin: 0 0 8px;

  color: #ffffff;

  font-size: 15px;
  font-weight: 800;
}

.footer-column h4::after {
  content: "";

  display: block;

  width: 28px;
  height: 3px;

  margin-top: 7px;

  border-radius: 10px;

  background: #38bdf8;
}

.footer-column a {
  position: relative;

  color: #bae6fd;

  text-decoration: none;

  font-size: 13.5px;

  transition:
    color .25s ease,
    transform .25s ease;
}

.footer-column a::before {
  content: "›";

  display: inline-block;

  margin-right: 7px;

  color: #38bdf8;

  font-size: 17px;

  transition: transform .25s ease;
}

.footer-column a:hover {
  color: #ffffff;

  transform: translateX(5px);

  text-decoration: none;
}

.footer-column a:hover::before {
  transform: translateX(3px);
}


/* FOOTER BOTTOM */

.footer-bottom {
  position: relative;
  z-index: 2;

  max-width: 1200px;

  margin: 0 auto;

  padding: 21px 30px;

  border-top: 1px solid rgba(186,230,253,.18);

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  color: #7dd3fc;

  font-size: 11.5px;

  line-height: 1.5;
}

.footer-bottom span:first-child {
  color: #bae6fd;
}

.footer-bottom span:last-child {
  color: #7dd3fc;
}


/* =========================================================
   FOOTER FOCUS
   ========================================================= */

.footer-column a:focus {
  outline: 2px solid #38bdf8;

  outline-offset: 4px;

  border-radius: 3px;
}


/* =========================================================
   ANIMATIONS
   ========================================================= */

@keyframes cfa-fade-up {

  from {
    opacity: 0;
    transform: translateY(25px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }

}

@keyframes cfa-gradient {

  0% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0% 50%;
  }

}

@keyframes cfa-float {

  0%,
  100% {
    transform: translateY(0) scale(1);
  }

  50% {
    transform: translateY(-20px) scale(1.05);
  }

}


/* =========================================================
   RESPONSIVE - TABLET
   ========================================================= */

@media (max-width: 950px) {

  .cfa-services-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .cfa-team-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-container {
    grid-template-columns: 1.5fr 1fr 1fr;

    gap: 40px;
  }

}


/* =========================================================
   RESPONSIVE - MOBILE
   ========================================================= */

@media (max-width: 700px) {

  .cfa-hero {
    padding: 80px 20px;
  }

  .cfa-hero h1 {
    font-size: 30px;
  }

  .cfa-hero p {
    font-size: 14px;
  }


  .cfa-welcome,
  .cfa-services,
  .cfa-about,
  .cfa-contact {
    padding: 60px 20px;
  }


  .cfa-welcome-points {
    grid-template-columns: 1fr;
  }


  .cfa-services-grid {
    grid-template-columns: repeat(2, 1fr);
  }


  .cfa-contact-grid {
    grid-template-columns: 1fr;
  }


  .footer-container {
    grid-template-columns: 1fr;

    gap: 35px;

    padding:
      0 24px
      38px;
  }


  .footer-brand {
    max-width: 100%;
  }


  .footer-bottom {
    padding:
      18px 24px;

    flex-direction: column;

    align-items: flex-start;

    gap: 6px;
  }

}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 450px) {

  .cfa-hero h1 {
    font-size: 26px;
  }

  .cfa-services-grid {
    grid-template-columns: 1fr;
  }

  .cfa-team-grid {
    grid-template-columns: 1fr;
  }

  .footer-container {
    padding-left: 18px;
    padding-right: 18px;
  }

  .footer-bottom {
    padding-left: 18px;
    padding-right: 18px;
  }

}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .cfa-hero,
  .cfa-hero::before,
  .cfa-hero::after,
  .cfa-hero-inner {
    animation: none;
  }

  .cfa-service-card,
  .cfa-team-card,
  .cfa-contact-card,
  .cfa-welcome-point,
  .cfa-hero-btn,
  .footer-column a,
  .footer-column a::before {
    transition: none;
  }

}
/* =========================================================
   FOOTER
   ========================================================= */

