   RESPONSIVE - TABLET
   ========================================================= */

@media (max-width: 950px) {

  .cfa-services-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .cfa-team-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-container {
    grid-template-columns: 1.5fr 1fr 1fr;

    gap: 40px;
  }

}


/* =========================================================
   RESPONSIVE - MOBILE
   ========================================================= */

@media (max-width: 700px) {

  .cfa-hero {
    padding: 80px 20px;
  }

  .cfa-hero h1 {
    font-size: 30px;
  }

  .cfa-hero p {
    font-size: 14px;
  }


  .cfa-welcome,
  .cfa-services,
  .cfa-about,
  .cfa-contact {
    padding: 60px 20px;
  }


  .cfa-welcome-points {
    grid-template-columns: 1fr;
  }


  .cfa-services-grid {
    grid-template-columns: repeat(2, 1fr);
  }


  .cfa-contact-grid {
    grid-template-columns: 1fr;
  }


  .footer-container {
    grid-template-columns: 1fr;

    gap: 35px;

    padding:
      0 24px
      38px;
  }


  .footer-brand {
    max-width: 100%;
  }


  .footer-bottom {
    padding:
      18px 24px;

    flex-direction: column;

    align-items: flex-start;

    gap: 6px;
  }

}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 450px) {

  .cfa-hero h1 {
    font-size: 26px;
  }

  .cfa-services-grid {
    grid-template-columns: 1fr;
  }

  .cfa-team-grid {
    grid-template-columns: 1fr;
  }

  .footer-container {
    padding-left: 18px;
    padding-right: 18px;
  }

  .footer-bottom {
    padding-left: 18px;
    padding-right: 18px;
  }

}


/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .cfa-hero,
  .cfa-hero::before,
  .cfa-hero::after,
  .cfa-hero-inner {
    animation: none;
  }

  .cfa-service-card,
  .cfa-team-card,
  .cfa-contact-card,
  .cfa-welcome-point,
  .cfa-hero-btn,
  .footer-column a,
  .footer-column a::before {
    transition: none;
  }

}
